// ============================================================================
//  "Fetch & Validate" Code node — pull EVERY visible product from the Salla
//  storefront API (looping the cursor ourselves) and flag products whose price
//  doesn't match the shown discount %.
//  Output = one item per MISMATCH (json), each with a thumbnail URL.
//  Uses this.helpers.httpRequest (works in the Code node) — no HTTP-node
//  pagination, which errors on an empty next URL.
// ============================================================================
const helpers = this.helpers;

const STORE_ID = '2053013347'; // legendsleepsa.com
const TOLERANCE_SAR = 1; // flag if price is off from shown-% price by >= this

function num(v) {
	if (v == null) return null;
	const n = parseFloat(String(v).replace(/,/g, ''));
	return isNaN(n) ? null : n;
}
function round2(n) {
	return Math.round((n + Number.EPSILON) * 100) / 100;
}

let url = `https://api.salla.dev/store/v1/products?per_page=50`;
let totalProducts = 0;
let onSale = 0;
const out = [];
let guard = 0;

while (url && guard < 300) {
	guard++;
	const res = await helpers.httpRequest({
		method: 'GET',
		url,
		headers: { 'store-identifier': STORE_ID },
		json: true,
	});
	const products = Array.isArray(res.data) ? res.data : [];
	for (const p of products) {
		totalProducts++;
		if (!p.is_on_sale) continue;
		onSale++;

		const regular = num(p.regular_price);
		const current = num(p.price != null ? p.price : p.sale_price);
		const m = String(p.promotion_title ?? '').match(/([0-9]+)\s*%/);
		const shownPct = m ? parseInt(m[1], 10) : null;
		if (!(regular && current && shownPct)) continue;

		const expected = round2(regular * (1 - shownPct / 100));
		const actualPct = Math.round((1 - current / regular) * 1000) / 10;
		const diff = round2(current - expected);

		if (Math.abs(diff) >= TOLERANCE_SAR) {
			const image = typeof p.image === 'string' ? p.image : p.image && p.image.url;
			const purl = String(p.url ?? '');
			const codeM = purl.match(/\/(?:ar|en)\/([A-Za-z0-9]+)\/?$/);
			out.push({
				json: {
					code: codeM ? codeM[1] : '',
					url: purl,
					name: p.name,
					original: regular,
					current,
					shownPct,
					expected,
					actualPct,
					diff,
					thumbUrl: image
						? `https://cdn.salla.sa/cdn-cgi/image/width=120,quality=70/${image}`
						: null,
				},
			});
		}
	}
	url = res.cursor && res.cursor.next ? res.cursor.next : null;
}

// always emit at least one item so the report + email still run when clean
if (out.length === 0) {
	return [{ json: { _summary: true, mismatches: 0, totalProducts, onSale } }];
}
// stamp the summary onto the first item for the report/email
out[0].json._totalProducts = totalProducts;
out[0].json._onSale = onSale;
return out;

// ============================================================================
//  "Build PDF" Code node — render the mismatch report as a PDF with thumbnails.
//  Input  = mismatch items from "Fetch & Validate" (json, incl. thumbUrl).
//  Fetches each thumbnail itself via httpRequest, embeds it, and builds a
//  paginated report. Requires `pdf-lib`. Latin/number text only (pdf-lib can't
//  shape Arabic) — products are identified by code + image + link.
// ============================================================================
const { PDFDocument, StandardFonts, rgb } = require('pdf-lib');
const helpers = this.helpers;

const all = $input.all().map((i) => i.json);
const rows = all.filter((r) => !r._summary && r.code !== undefined);
const totalProducts = all[0] && (all[0]._totalProducts || all[0].totalProducts);
const onSale = all[0] && (all[0]._onSale || all[0].onSale);

const doc = await PDFDocument.create();
const font = await doc.embedFont(StandardFonts.Helvetica);
const bold = await doc.embedFont(StandardFonts.HelveticaBold);

const W = 595, H = 842, M = 40, ROW = 78;
let page, y;
function newPage() {
	page = doc.addPage();
	page.setSize(W, H);
	y = H - M;
}
function text(s, x, yy, size, f, color) {
	page.drawText(String(s), { x, y: yy, size, font: f || font, color: color || rgb(0, 0, 0) });
}
newPage();

text('Legend Sleep - Discount Audit', M, y, 18, bold, rgb(0.12, 0.12, 0.42));
y -= 22;
text(
	`Mismatches: ${rows.length}` +
		(onSale ? `   (of ${onSale} on-sale / ${totalProducts} products)` : ''),
	M,
	y,
	11,
	font,
);
y -= 10;
page.drawRectangle({ x: M, y, width: W - 2 * M, height: 1, color: rgb(0.6, 0.6, 0.6) });
y -= 18;

for (const r of rows) {
	if (y < M + ROW) newPage();

	// fetch + embed the thumbnail
	if (r.thumbUrl) {
		try {
			const raw = await helpers.httpRequest({ method: 'GET', url: r.thumbUrl, encoding: 'arraybuffer' });
			const buf = Buffer.from(raw);
			if (buf.length > 100) {
				const isJpg = buf[0] === 0xff && buf[1] === 0xd8;
				const img = isJpg ? await doc.embedJpg(buf) : await doc.embedPng(buf);
				page.drawImage(img, { x: M, y: y - 58, width: 58, height: 58 });
			}
		} catch (e) {
			/* skip image */
		}
	}

	const tx = M + 72;
	const sign = r.diff > 0 ? '+' : '';
	text(r.code, tx, y - 8, 12, bold);
	text(`Original ${r.original}   Current ${r.current}   Shown ${r.shownPct}%`, tx, y - 24, 10, font);
	text(
		`Should be ${r.expected}   Real ${r.actualPct}%   Off by ${sign}${r.diff} SAR`,
		tx,
		y - 39,
		10,
		bold,
		rgb(0.8, 0, 0),
	);
	text(r.url, tx, y - 54, 8, font, rgb(0.3, 0.3, 0.7));

	y -= ROW;
	page.drawRectangle({ x: M, y: y + 8, width: W - 2 * M, height: 0.5, color: rgb(0.85, 0.85, 0.85) });
}

const fileName = 'discount-audit.pdf';
const bytes = await doc.save();
const bin = await helpers.prepareBinaryData(Buffer.from(bytes), fileName, 'application/pdf');

let recipient = '';
try {
	recipient = $('On form submission').first().json['Send To Email'];
} catch (e) {
	/* scheduled run without a form */
}

return [{ json: { mismatches: rows.length, totalProducts, onSale, fileName, recipient }, binary: { data: bin } }];
